    // An uncheck is kept PER PAYMENT (key 'p:' + payment id), not per cluster id: a slider can split a cluster's
    // row or move a payment to another row, and an uncheck keyed by the cluster id was lost then. A row is checked
    // when none of its payments is unchecked. A slider can move a checked payment into a cluster whose other payments
    // the user unchecked: the cluster then shows as TWO rows, one checked and one unchecked, so an uncheck never
    // spreads to a payment the user did not uncheck (review round 2, finding 5). A checked part of one payment is no
    // group: that payment stays ungrouped. key: the row's DOM and hover key; id stays the cluster id for the scores.
    const isOff = (p) => !!st.offRows['p:' + p.id];
