        badge: b.t, tip: b.tip, tipId: 'ii-tip-' + p.id, tipOpen: h.open, tipShow: h.show, tipHide: h.hide, badgeStyle: pill(b.col || TAG[b.tone]),
        sideStyle: 'display: flex; width: 100%; gap: 8px; padding: 6px 14px 6px 12px; border: 0; cursor: pointer; font-size: 14px; color: ' + (on ? '#e6e9ef' : '#b4bccb') + '; border-left: 2px solid ' + (on ? '#4c9aff' : 'transparent') + '; background: ' + (on ? '#18212d' : 'transparent'),
        pick: () => this.setState({ cur: p.id }), ignore: () => place(p.id, 'IGNORED'), group: () => openInput(p.id),
        quick: created.slice(0, 9).map((n, i) => ({ num: String(i + 1), name: n, label: 'Add to ' + n + ' (key ' + (i + 1) + ')', add: () => place(p.id, n) })),
