    const fmt2 = (v) => '$' + v.toLocaleString('en-US', { minimumFractionDigits: 2, maximumFractionDigits: 2 });
    const range = (ps) => { const xs = ps.map((p) => Math.abs(p.a)); const lo = Math.min(...xs), hi = Math.max(...xs); return lo === hi ? { kind: 'Fixed', amount: money2(lo) } : { kind: 'Variable', amount: fmt2(lo) + ' – ' + fmt2(hi) }; };
    const sideOf = (g) => (sum(g.pays) >= 0 ? 'REVENUE' : 'EXPENSES');
