    const byPid = Object.assign({}, ...pays.map((p) => {
      const f = home[p.id], own = ownCand(f, p);
      const all = (own ? [K.evalOne(p, own, samePayee)] : []).concat(clusters.filter((g) => g !== f).map((g) => K.evalOne(p, whole[g.id], samePayee))), R = K.rank(all);
      return { [p.id]: { p, list: R.list, of: R.of, pNew: R.pNew, ignored: false, home: f.id, alone: f.ps.length === 1 } };
    }));
